-- ============================================================
-- 로컬 검증 전용 더미 데이터(화면별 10건). 운영 DB에 절대 적용하지 말 것.
-- IDX 는 101~110 / 로그는 201~210 — 시퀀스 시작값(1000) 아래라 앱이 만드는 행과 충돌하지 않는다.
-- 새 테이블은 만들지 않는다. FIDO 로그는 기존 파티션 FIDO_LOGS_20210102 를 쓴다.
-- 다시 적용하려면 먼저 삭제: DELETE ... WHERE IDX BETWEEN 101 AND 110 (아래 "삭제" 절 참고).
-- ============================================================
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK
WHENEVER OSERROR EXIT FAILURE ROLLBACK
DECLARE
  v_db VARCHAR2(128);
BEGIN
  SELECT SYS_CONTEXT('USERENV', 'DB_NAME') INTO v_db FROM DUAL;
  IF UPPER(v_db) NOT IN ('FREE', 'FREEPDB1') THEN  -- CDB 접속이면 FREE, PDB 접속이면 FREEPDB1
    RAISE_APPLICATION_ERROR(-20999, '중단: 로컬 검증 전용 스크립트다. 대상 DB_NAME=' || v_db || ' (기대값 FREE 또는 FREEPDB1)');
  END IF;
END;
/

-- 1. 앱 ID (APPID) — 고객사 1

-- 2. 멤버코드 (APPSERVER)

-- 3. 서명 (SIGN)

-- 4. 거래 해시 (TRANSACTIONHASH)

-- 5. 거래 확인 (TRANSACTION_CONFIRMATION)

-- 6. 예외 로그 (CCFA_EXCEPTIONS)

-- 7. 라이선스 (CCFA_LICENSE)

-- 8. AAID 정책 (CRITERIA) — 전역

-- 9. 메일/SMS 큐 (CCFA_MAILING)

-- 10. 에러 코드 (CCFA_ERROR_TABLE) — UAF 1.x 응답 코드

-- 11. FIDO2 메타데이터 (FIDO2_METADATA) — 전역

-- 12. FIDO 로그 (FIDO_LOGS_20210102, 기존 파티션) — 모니터링이 잡을 반복 패턴 포함
--    SN-D001: 3건이 3초 안에 / SN-D002: 2건이 20초 간격(정책 30초 안) / 나머지는 간격이 큼 / 마지막 1건은 고객사 2

-- 13. 운영자 (CCFA_MANAGER) — 고객사 1, 비밀번호는 kbadmin 과 동일(Company1234!)

COMMIT;

-- 삭제(되돌리기):
--   DELETE FROM APPID WHERE IDX BETWEEN 101 AND 110;  (APPSERVER, SIGN, TRANSACTIONHASH, TRANSACTION_CONFIRMATION,
--   CCFA_EXCEPTIONS, CCFA_LICENSE, CRITERIA, CCFA_MAILING, FIDO2_METADATA, CCFA_MANAGER 도 같은 범위)
--   DELETE FROM FIDO_LOGS_20210102 WHERE IDX BETWEEN 201 AND 210;
--   DELETE FROM CCFA_ERROR_TABLE WHERE ERROR_CODE IN ('1400','1401','1403','1404','1408','1480','1481','1490','1491','1500');
